products = ["pen", "book", "lamp", "mug", "desk"]
prices = [1.5, 12.0, 24.99, 6.25]

for product, price in zip(products, prices):
    print(f"{product}: ${price:.2f}")

stock = [100, 104, 101, 101, 107, 110]
rises = 0
for yesterday, today in zip(stock, stock[1:]):
    if today > yesterday:
        rises += 1

print("Rises:", rises)
